import Image from 'next/image';
import { cn } from '@/lib/tones';

const RATIO = 502 / 173; // master logo is 502×173

const SRC = {
  /** White text — for dark surfaces (header, hero, PDF cover). */
  light: '/brand/morosoft-logo.webp',
  /** Dark text — for light surfaces. Generated by `pnpm --filter @seo/web icons`. */
  dark: '/brand/morosoft-logo-dark.webp',
};

/**
 * Morosoft logo, optionally followed by the product name.
 * `tone` names the text colour: 'light' on dark backgrounds, 'dark' on light ones.
 */
export function Logo({
  tone = 'light',
  height = 40,
  product = 'SEO Audit',
  priority = false,
  className,
}: {
  tone?: 'light' | 'dark';
  height?: number;
  product?: string | null;
  priority?: boolean;
  className?: string;
}) {
  return (
    <span className={cn('inline-flex items-center gap-3', className)}>
      <Image
        src={SRC[tone]}
        alt="Morosoft — Tech & Growth Partner"
        width={Math.round(height * RATIO)}
        height={height}
        priority={priority}
        unoptimized
        className="h-auto max-w-none"
        style={{ width: Math.round(height * RATIO), height }}
      />
      {product && (
        <span
          className={cn(
            'hidden border-l pl-3 font-display sm:inline text-[13px] font-semibold uppercase tracking-[0.08em]',
            tone === 'light' ? 'border-white/15 text-white/60' : 'border-border-strong text-ink-3',
          )}
        >
          {product}
        </span>
      )}
    </span>
  );
}
